-- 溶媒なしの物理回収と小規模比較。既存表のデータのみ。一度だけ適用。
begin;
select set_config('amd.cost_change_reason','まさ指示: 溶媒なし物理回収の速度/回収率と年1万Lの採算条件を比較',true);
do $$ begin
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_model_id)) from project_cost_models t where cost_model_id='cm_p21_fuel_260914') is distinct from '8a0cf7b204822d8e7555af69ecc9af12' then raise exception 'fuel model changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_fuel_260914') is distinct from 'cdf75a6c3a9eb70681d5a9f47d273d6b' then raise exception 'fuel assumptions changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_item_id)) from project_cost_items t where cost_model_id='cm_p21_fuel_260914') is distinct from '37269b68b120e3efdb272054f91cdcad' then raise exception 'fuel items changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_task_id)) from project_cost_tasks t where cost_model_id='cm_p21_fuel_260914') is distinct from 'e70f8ccf8c7eb05ef1b3aa91d13b0910' then raise exception 'fuel tasks changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_note_id)) from project_cost_notes t where cost_model_id='cm_p21_fuel_260914') is distinct from 'b5a76c47ced4a1e2aa34597b4f50fd75' then raise exception 'fuel notes changed'; end if;
 if (select md5(string_agg(to_jsonb(t)::text,',' order by cost_assumption_id)) from project_cost_assumptions t where cost_model_id='cm_p21_260820') is distinct from '14615c6754d08102b739cfeaf72462b6' then raise exception 'effluent changed'; end if;
end $$;
update project_cost_models set summary_md='物理回収・溶媒循環・全槽保持を切り替え、分泌速度・回収率と追加装置・分析頻度から小規模の採算条件を比較する。年産は排水事業の菌体使用量から出力。',version_label='261017 溶媒なしの物理回収・小規模比較',system_scope_md='物理回収の基準は人工照明基準0.01g/L/日、回収60%の独立した設計仮定。排水側の太陽光比50%を掛ける。回収装置1台48万円、能力1kg-回収FFA/時・24h/日・300日/年、台数を切上げ。保守年5万円/台、ろ材洗浄廃棄8円/kg、電力0.5kWh/kg、脱水3kg水/kg・熱2.6MJ/kg水・効率70%。全培養費は排水側。分析装置200万円は購入、既存FAME設備は共用する条件。外部分析は月1回の保存値を維持し、年2回/1回、乾燥水分1kg/kgとFAME設備500万円購入の比較を表示。外部分析の仕様・頻度と装置能力は要確認。',updated_at=now() where cost_model_id='cm_p21_fuel_260914';
update project_cost_assumptions set label='脂肪酸の回収方式',value_text='physical',updated_at=now() where cost_assumption_id='caf_loop_mode';
update project_cost_assumptions set value=50.58802639740744,updated_at=now() where cost_assumption_id='caf_small_inventory_recovery_share';
update project_cost_notes set body_md='回収方式を上部で選ぶ。物理回収は溶媒なしの分泌速度と回収率を入力し、集油・ろ過・脱水・FAME化・分析・出荷の追加費を計算する。小規模比較では年産目安に要る菌体の対象割合を逆算し、設備と分析頻度を比べる。適用は試算条件を変更し、保存操作で正本へ反映する。',updated_at=now() where cost_note_id='cnf_guide';
update project_cost_assumptions set note=note||' 機械脱水で減らせる場合は、その後に熱で除く水分だけを入力。' where role_key='fuel_physical_water' and cost_model_id='cm_p21_fuel_260914';
update project_cost_notes set title='溶媒循環の共用設備条件',updated_at=now() where cost_note_id='cnf_min_boundary_261017';
update project_cost_notes set body_md=replace(body_md,'現在の循環回収は溶媒を用いる方式の比較であり必須設備ではない。','画面では物理回収に独立した分泌速度・回収率を入力する。溶媒循環との比較も可能。'),updated_at=now() where cost_note_id='cnf_physical_recovery_261017';
commit;
