insert into project_cost_notes (cost_note_id,cost_model_id,section,title,body_md,source_label,source_url,visibility,sort_order) values ('cnf_physical_small_261017','cm_p21_fuel_260914','caveat','物理回収と小規模設備の試算条件','物理回収の基準は人工照明基準0.01g/L/日、回収60%の独立した設計仮定。排水側の太陽光比50%を掛ける。回収装置1台48万円、能力1kg-回収FFA/時・24h/日・300日/年、台数を切上げ。保守年5万円/台、ろ材洗浄廃棄8円/kg、電力0.5kWh/kg、脱水3kg水/kg・熱2.6MJ/kg水・効率70%。全培養費は排水側。分析装置200万円は購入、既存FAME設備は共用する条件。外部分析は月1回の保存値を維持し、年2回/1回、乾燥水分1kg/kgとFAME設備500万円購入の比較を表示。外部分析の仕様・頻度と装置能力は要確認。','内部設計とメーカー公表例','https://www.nikuni-onlineshop.jp/view/item/005001000003','amd_internal',35);
